"use client"

/**
 * Brand marks for payment processors.
 *
 * The provider descriptor already carries a `logoRef` (see
 * `packages/payments/src/default-catalog.ts`); this module is the one place
 * that resolves that reference to something renderable. Resolution is by
 * reference rather than by provider id so a processor can be renamed, or two
 * ids can share a brand, without touching the artwork.
 *
 * Marks are inline SVG, matching the rest of the repo — there is no static
 * asset pipeline here, and an inline mark costs no request and survives a
 * strict CSP.
 *
 * Every mark sits on the same white plate. Processor logos are fixed-colour
 * brand assets that cannot be recoloured per theme, so a constant light
 * background is what keeps one row looking like the next in both light and
 * dark — the alternative is a dark logo vanishing into a dark card.
 */

import { cn } from "@voyant-travel/ui/lib/utils"
import type { ComponentProps, ComponentType } from "react"

/**
 * A processor's visual identity.
 *
 * `mark` is optional: a brand with no bundled artwork still gets a stable,
 * legible monogram on the same plate.
 */
interface PaymentProviderBrand {
  mark?: ComponentType<ComponentProps<"svg">>
  /** Ink for the mark, applied through `currentColor`. */
  ink?: string
}

