/**
 * Known processor brands, keyed by the descriptor's `logoRef`.
 *
 * To add a processor: drop its SVG in as a component above and reference it
 * here. A brand with no artwork yet needs no entry at all — it falls through
 * to the monogram.
 */
const paymentProviderBrands: Record<string, PaymentProviderBrand> = {
  "voyant-pay": { mark: VoyantPayMark, ink: "text-black" },
  netopia: { mark: NetopiaMark, ink: "text-[#49458d]" },
}

/**
 * Up to two initials for a processor, skipping words that carry no identity.
 *
 * "Netopia Payments" reads as `N`, not `NP` — the second word is a category,
 * not part of the brand, and a monogram that encodes it is noise.
 */
export function paymentProviderInitials(displayName: string): string {
  const generic = new Set(["payments", "payment", "pay", "checkout", "inc", "ltd", "sa", "srl"])
  const words = displayName
    .split(/[\s\-_]+/)
    .map((word) => word.replace(/[^\p{L}\p{N}]/gu, ""))
    .filter((word) => word.length > 0)
  const identifying = words.filter((word) => !generic.has(word.toLowerCase()))
  const source = identifying.length > 0 ? identifying : words
  return source
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase() ?? "")
    .join("")
}

export interface PaymentProviderLogoProps {
  /** The descriptor's `logoRef`; falls back to the provider id. */
  logoRef?: string
  providerId: string
  displayName: string
  className?: string
}

/**
 * A processor's mark on a fixed plate.
 *
 * The plate is one size regardless of which brand resolves, and each mark is
 * height-constrained and letterboxed inside it, so logos of different aspect
 * ratios still land on one left edge at one optical weight. That is what makes
 * an integrations list read as a list rather than as a pile of logos.
 */
export function PaymentProviderLogo({
  logoRef,
  providerId,
  displayName,
  className,
}: PaymentProviderLogoProps) {
  const brand = paymentProviderBrands[logoRef ?? ""] ?? paymentProviderBrands[providerId]
  const Mark = brand?.mark

  return (
    <span
      aria-hidden="true"
      className={cn(
        "flex h-11 w-32 shrink-0 items-center justify-center rounded-md bg-white px-3 ring-1 ring-black/10",
        brand?.ink ?? "text-neutral-600",
        className,
      )}
    >
      {Mark ? (
        <Mark className="h-6 w-full" />
      ) : (
        <span className="text-sm font-semibold tracking-wide">
          {paymentProviderInitials(displayName)}
        </span>
      )}
    </span>
  )
}
